def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if len(pts) < 2:
        return out

    # Build a minimum spanning rectilinear connection between the markers.
    # Each new marker is joined to the existing connected network by a
    # shortest horizontal/vertical route.
    connected = {pts[0]}
    remaining = set(pts[1:])

    while remaining:
        best = None
        for p in remaining:
            for q in connected:
                dist = abs(p[0] - q[0]) + abs(p[1] - q[1])
                candidate = (dist, p, q)
                if best is None or candidate < best:
                    best = candidate

        _, (r1, c1), (r2, c2) = best
        # Route horizontally first, then vertically.
        step = 1 if c2 >= c1 else -1
        for c in range(c1, c2 + step, step):
            if out[r1][c] == 0:
                out[r1][c] = 3
        step = 1 if r2 >= r1 else -1
        for r in range(r1, r2 + step, step):
            if out[r][c2] == 0:
                out[r][c2] = 3

        connected.add((r1, c1))
        remaining.remove((r1, c1))

    return out
