    rs = sorted(r for r, c in pts)
    cs = sorted(c for r, c in pts)
    rlo, rhi = min(rs), max(rs)
    clo, chi = min(cs), max(cs)

    def mark(r, c):
        if out[r][c] == 0:
            out[r][c] = 3

    # Form a central spine along the longer spread of the marker pattern,
    # with each marker joined to it by a perpendicular segment.
    if rhi - rlo > chi - clo:
        cspine = cs[len(cs) // 2]
        for r in range(rlo, rhi + 1):
            mark(r, cspine)
        for r, c in pts:
            for x in range(min(c, cspine), max(c, cspine) + 1):
                mark(r, x)
    else:
        rspine = rs[len(rs) // 2]
        for c in range(clo, chi + 1):
            mark(rspine, c)
        for r, c in pts:
            for y in range(min(r, rspine), max(r, rspine) + 1):
                mark(y, c)

    return out
